PRAGMA foreign_keys = ON;
-- مرکز اقتصادی یکپارچه هر ساختمان
CREATE TABLE IF NOT EXISTS market_stores(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,vendor_name TEXT NOT NULL,store_name TEXT NOT NULL,category TEXT NOT NULL,contact_phone TEXT,opening_hours TEXT,delivery_modes_json TEXT NOT NULL DEFAULT '[]',commission_percent REAL NOT NULL DEFAULT 0 CHECK(commission_percent BETWEEN 0 AND 100),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','active','suspended','closed')),created_at TEXT NOT NULL,updated_at TEXT);
CREATE INDEX IF NOT EXISTS idx_market_stores_building_status ON market_stores(building_id,status);
CREATE TABLE IF NOT EXISTS market_products(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,store_id TEXT NOT NULL REFERENCES market_stores(id) ON DELETE CASCADE,sku TEXT,title TEXT NOT NULL,description TEXT,category TEXT NOT NULL,image_storage_key TEXT,unit_label TEXT NOT NULL DEFAULT 'عدد',price_amount INTEGER NOT NULL CHECK(price_amount>=0),stock_quantity REAL NOT NULL DEFAULT 0 CHECK(stock_quantity>=0),is_available INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','unavailable','archived')),created_at TEXT NOT NULL,updated_at TEXT,UNIQUE(store_id,sku));
CREATE INDEX IF NOT EXISTS idx_market_products_store_status ON market_products(store_id,status,is_available);
CREATE TABLE IF NOT EXISTS market_orders(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,batch_id TEXT NOT NULL,order_number TEXT NOT NULL,unit_id TEXT REFERENCES units(id) ON DELETE SET NULL,customer_person_id TEXT REFERENCES people(id) ON DELETE SET NULL,customer_name TEXT NOT NULL,store_id TEXT NOT NULL REFERENCES market_stores(id),delivery_method TEXT NOT NULL CHECK(delivery_method IN('unit','lobby','pickup')),order_status TEXT NOT NULL DEFAULT 'placed' CHECK(order_status IN('placed','accepted','preparing','ready','out_for_delivery','delivered','cancelled','rejected')),payment_status TEXT NOT NULL DEFAULT 'pending' CHECK(payment_status IN('pending','paid','failed','refund_pending','refunded','settled')),subtotal_amount INTEGER NOT NULL CHECK(subtotal_amount>=0),delivery_fee_amount INTEGER NOT NULL DEFAULT 0 CHECK(delivery_fee_amount>=0),total_amount INTEGER NOT NULL CHECK(total_amount>=0),customer_phone TEXT,customer_note TEXT,placed_at TEXT NOT NULL,updated_at TEXT,UNIQUE(building_id,order_number));
CREATE INDEX IF NOT EXISTS idx_market_orders_building_status ON market_orders(building_id,order_status,placed_at);
CREATE INDEX IF NOT EXISTS idx_market_orders_store_status ON market_orders(store_id,order_status,placed_at);
CREATE INDEX IF NOT EXISTS idx_market_orders_unit ON market_orders(unit_id,placed_at);
CREATE TABLE IF NOT EXISTS market_order_items(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES market_orders(id) ON DELETE CASCADE,product_id TEXT REFERENCES market_products(id) ON DELETE SET NULL,product_title_snapshot TEXT NOT NULL,unit_price_amount INTEGER NOT NULL CHECK(unit_price_amount>=0),quantity REAL NOT NULL CHECK(quantity>0),line_total_amount INTEGER NOT NULL CHECK(line_total_amount>=0));
CREATE INDEX IF NOT EXISTS idx_market_order_items_order ON market_order_items(order_id);
CREATE TABLE IF NOT EXISTS market_payments(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,order_id TEXT NOT NULL REFERENCES market_orders(id) ON DELETE CASCADE,payment_method TEXT NOT NULL CHECK(payment_method IN('cash_on_delivery','pos_on_delivery','online_gateway','credit')),payment_status TEXT NOT NULL DEFAULT 'pending' CHECK(payment_status IN('pending','paid','failed','refund_pending','refunded','settled')),amount INTEGER NOT NULL CHECK(amount>=0),provider_reference TEXT,paid_at TEXT,created_at TEXT NOT NULL,updated_at TEXT);
CREATE INDEX IF NOT EXISTS idx_market_payments_order_status ON market_payments(order_id,payment_status);
CREATE TABLE IF NOT EXISTS market_deliveries(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,order_id TEXT NOT NULL UNIQUE REFERENCES market_orders(id) ON DELETE CASCADE,delivery_status TEXT NOT NULL DEFAULT 'queued' CHECK(delivery_status IN('queued','preparing','ready','assigned','in_transit','delivered','failed','returned')),courier_person_id TEXT REFERENCES people(id) ON DELETE SET NULL,courier_name TEXT,tracking_code TEXT,scheduled_at TEXT,delivered_at TEXT,delivery_proof_key TEXT,delivery_note TEXT,created_at TEXT NOT NULL,updated_at TEXT);
CREATE INDEX IF NOT EXISTS idx_market_deliveries_building_status ON market_deliveries(building_id,delivery_status,created_at);
